cd /logs/agent/sessions/projects/-workspace/c04d0ee3-1507-4573-94d0-03920898b379/tool-results/; python3 - <<'EOF'
import json,glob,collections
inscope={json.loads(l)['p']['Staff number'] for l in open('/workspace/work/nurses.jsonl') if json.loads(l)['p']['Unit']=='Acute Medicine' and json.loads(l)['p']['Site']=='MGH'}
recs={}
for f in sorted(glob.glob('mcp-LightNotion-search-*')):
    d=json.load(open(f))['output']
    for r in d['results']:
        recs[r['id']]=r
# per nurse counts
c=collections.Counter()
other=collections.Counter()
for r in recs.values():
    sn=(r.get('properties',{}).get('Staff number') or {}).get('value')
    if sn in inscope: c[(sn,r['parent_id'])]+=1
    else: other[r.get('parent_id')]+=1
for sn in sorted(inscope):
    print(sn, c[(sn,'db-roster-sep-oct-2026')], c[(sn,'db-shift-actuals-to-1014')], c[(sn,'db-shift-actuals-from-1015')])
print(other)
json.dump(recs,open('/workspace/work/recs.json','w'))
EOF

cd /workspace/work; python3 - <<'EOF'
import json,collections
recs=json.load(open('recs.json'))
types=collections.Counter(); keys=collections.Counter()
for r in recs.values():
    if r['parent_id'].startswith('db-shift') or r['parent_id'].startswith('db-roster'):
        p=r['properties']; types[(r['parent_id'],p['Type']['value'])]+=1
        keys[(r['parent_id'],tuple(sorted(p)))]+=1
for k,v in types.items(): print(k,v)
for k,v in keys.items(): print(k,v)
# sample
sn='49130'
rows=[r for r in recs.values() if r['properties'].get('Staff number',{}).get('value')==sn and r['parent_id']!='db-nurse-register']
rows.sort(key=lambda r:(r['properties']['Shift ref']['value'],r['parent_id']))
for r in rows:
    p={k:v['value'] for k,v in r['properties'].items()}
    print(r['parent_id'][3:12], {k:v for k,v in p.items() if k not in('Staff number',)})
EOF

